"""
Machine learning inference service and civil engineering mix calculations.
Loads model package once during application startup.
"""

import os
import json
import datetime
from typing import Dict, Any, Optional
import numpy as np
import pandas as pd
import joblib

from backend.config import MODEL_PATH, METRICS_PATH, HELD_OUT_PATH
from backend.schemas import (
    ConcreteMixInput,
    CalculatedMixProperties,
    PredictionResponse
)

ENGINEERING_DISCLAIMER = (
    "DISCLAIMER & ENGINEERING LIMITATIONS: This predicted compressive strength is generated by a statistical "
    "machine-learning regression model trained on the UCI Concrete Compressive Strength benchmark dataset. "
    "Actual concrete compressive strength in practice depends significantly on cement chemical composition, "
    "aggregate grading, particle shape, moisture correction, water quality, ambient mixing temperature, "
    "degree of compaction, and standard curing conditions (e.g., IS 516 / ASTM C39). This estimate is intended "
    "for preliminary educational and experimental comparison only and must NOT replace standard laboratory "
    "testing or code-compliant structural mix design (e.g., IS 10262, ACI 211, or BS EN 206)."
)


class MLService:
    def __init__(self):
        self._model_package: Optional[Dict[str, Any]] = None
        self._metrics_cache: Optional[Dict[str, Any]] = None
        self._held_out_cache: Optional[list] = None

    def load_model(self):
        """Loads the serialized model package and evaluation metrics."""
        if os.path.exists(MODEL_PATH):
            try:
                self._model_package = joblib.load(MODEL_PATH)
                print(f"[MLService] Successfully loaded model from {MODEL_PATH}")
            except Exception as e:
                print(f"[MLService] Failed to load model artifact: {e}")
                self._model_package = None
        else:
            print(f"[MLService] Warning: Model artifact not found at {MODEL_PATH}")
            self._model_package = None

        if os.path.exists(METRICS_PATH):
            try:
                with open(METRICS_PATH, "r") as f:
                    self._metrics_cache = json.load(f)
            except Exception as e:
                print(f"[MLService] Failed to load metrics JSON: {e}")
                self._metrics_cache = None

        if os.path.exists(HELD_OUT_PATH):
            try:
                with open(HELD_OUT_PATH, "r") as f:
                    self._held_out_cache = json.load(f)
            except Exception as e:
                print(f"[MLService] Failed to load held-out predictions: {e}")
                self._held_out_cache = None

    @property
    def is_model_loaded(self) -> bool:
        return self._model_package is not None and "model" in self._model_package

    @property
    def model_name(self) -> str:
        return self._model_package.get("model_name", "Unknown") if self._model_package else "None"

    @property
    def model_version(self) -> str:
        return self._model_package.get("version", "1.0.0") if self._model_package else "None"

    def get_metrics_data(self) -> Dict[str, Any]:
        if self._metrics_cache is None:
            # Try reloading if file created after startup
            if os.path.exists(METRICS_PATH):
                with open(METRICS_PATH, "r") as f:
                    self._metrics_cache = json.load(f)
        if self._metrics_cache is None:
            raise FileNotFoundError("Metrics summary artifact not found. Please run the training pipeline first.")
        
        # Attach held-out sample points
        if self._held_out_cache is None and os.path.exists(HELD_OUT_PATH):
            with open(HELD_OUT_PATH, "r") as f:
                self._held_out_cache = json.load(f)
        
        result = dict(self._metrics_cache)
        result["held_out_samples"] = self._held_out_cache or []
        return result

    def get_model_info(self) -> Dict[str, Any]:
        metrics = self.get_metrics_data()
        return {
            "model_name": self.model_name,
            "model_version": self.model_version,
            "trained_timestamp": self._model_package.get("trained_at", metrics.get("trained_timestamp", "")),
            "feature_names": self._model_package.get("feature_names", metrics.get("feature_names", [])),
            "target_name": self._model_package.get("target_name", metrics.get("target_name", "compressive_strength")),
            "dataset_info": metrics.get("dataset_info", {}),
            "features_metadata": metrics.get("features_metadata", {})
        }

    def predict(self, mix: ConcreteMixInput) -> PredictionResponse:
        """
        Executes prediction using the trained regression model.
        Features are passed in the strict standard order.
        Calculates engineering mix parameters.
        """
        if not self.is_model_loaded:
            # Attempt hot-reload if model was trained while service was running
            self.load_model()
            if not self.is_model_loaded:
                raise RuntimeError(
                    "Trained machine learning model artifact is not available on the server. "
                    "Please run the model training script ('python ml/train.py') to generate the model artifact."
                )

        model = self._model_package["model"]
        feature_order = self._model_package.get(
            "feature_names",
            ["cement", "slag", "fly_ash", "water", "superplasticizer", "coarse_aggregate", "fine_aggregate", "age"]
        )

        # 1. Engineering Calculations (Not predictions, pure physical mix design balances)
        total_binder = mix.cement + mix.slag + mix.fly_ash
        if total_binder <= 0:
            raise ValueError("Total binder content must be greater than zero.")

        w_b_ratio = mix.water / total_binder
        total_aggregate = mix.coarse_aggregate + mix.fine_aggregate
        fine_agg_ratio = mix.fine_aggregate / total_aggregate if total_aggregate > 0 else 0.0
        fresh_density = total_binder + mix.water + mix.superplasticizer + total_aggregate

        calc_props = CalculatedMixProperties(
            total_binder_kg_m3=round(total_binder, 2),
            water_to_binder_ratio=round(w_b_ratio, 3),
            total_aggregate_kg_m3=round(total_aggregate, 2),
            fine_to_total_aggregate_ratio=round(fine_agg_ratio, 3),
            estimated_fresh_density_kg_m3=round(fresh_density, 1)
        )

        # 2. Prepare Feature Vector in exact feature order
        feature_values = {
            "cement": mix.cement,
            "slag": mix.slag,
            "fly_ash": mix.fly_ash,
            "water": mix.water,
            "superplasticizer": mix.superplasticizer,
            "coarse_aggregate": mix.coarse_aggregate,
            "fine_aggregate": mix.fine_aggregate,
            "age": mix.age
        }

        # Build single-row DataFrame to preserve column names and avoid sklearn feature warnings
        df_input = pd.DataFrame([[feature_values[f] for f in feature_order]], columns=feature_order)

        # 3. Predict Compressive Strength in MPa
        raw_pred = model.predict(df_input)[0]
        # Physical lower bound for compressive strength is 0
        predicted_strength = max(0.0, float(raw_pred))

        return PredictionResponse(
            predicted_strength_mpa=round(predicted_strength, 2),
            model_name=self.model_name,
            model_version=self.model_version,
            prediction_timestamp=datetime.datetime.now(datetime.timezone.utc).isoformat(),
            calculated_properties=calc_props,
            submitted_mix=feature_values,
            disclaimer=ENGINEERING_DISCLAIMER
        )


# Singleton service instance
ml_service = MLService()
